  "overview": {
    "text": "Sydney is the capital of New South Wales, on Australia’s east coast; its wider metropolitan region, Greater Sydney, had the largest population among Australia’s capital-city regions in 2021. The city’s historic center grew around Sydney Cove on Port Jackson, where the British First Fleet arrived in 1788 and established a convict settlement. Sydney’s story also includes much older Aboriginal histories: the Sydney Opera House site at Bennelong Point is on Tubowgule, acknowledged by the Opera House as Gadigal Country. Danish architect Jørn Utzon designed the Opera House, whose sculptural shell-like roof forms evoke harbour sails and have become a defining city landmark.",
    "source_urls": [
      "https://www.nsw.gov.au/about-nsw/key-facts-about-nsw",
      "https://www.abs.gov.au/statistics/people/people-and-communities/location-census/2021",
      "https://www.cityofsydney.nsw.gov.au/history/history-city-sydney-council",
      "https://www.sydneyoperahouse.com/our-story/tubowgule",
      "https://www.sydneyoperahouse.com/our-story/jorn-utzon"
    ]
  },
  "key_facts": [
    {
      "text": "Sydney is New South Wales’s capital and lies on the state’s eastern coast.",
      "source_urls": [
        "https://www.nsw.gov.au/about-nsw/key-facts-about-nsw"
      ]
    },
    {
      "text": "In the 2021 Census, Greater Sydney had a larger population than any other Australian Greater Capital City Statistical Area.",
      "source_urls": [
        "https://www.abs.gov.au/statistics/people/people-and-communities/location-census/2021"
      ]
    },
    {
      "text": "The British settlement was established in 1788 around Sydney Cove after the First Fleet entered Port Jackson; Sydney was incorporated as a city in 1842.",
      "source_urls": [
        "https://www.cityofsydney.nsw.gov.au/history/history-city-sydney-council"
      ]
    },
    {
      "text": "The Opera House acknowledges its site, Tubowgule at Bennelong Point, as Gadigal Country; Bennelong Point is named for Woollarawarre Bennelong of the Wangal people.",
      "source_urls": [
        "https://www.sydneyoperahouse.com/our-story/tubowgule"
      ]
    },
    {
      "text": "Danish architect Jørn Utzon won the Opera House design competition in 1957; its shell-shaped roofs were designed to evoke Sydney’s harbour sails and cliffs.",
      "source_urls": [
        "https://www.sydneyoperahouse.com/our-story/jorn-utzon"
      ]
    }
  ],
